const store={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
// The game was called Note Catcher until 3 Nov 2026: carry saved stats and settings over once, then drop the old keys.
try{for(const k of ['v1','stage','lang','notes']){const old=localStorage.getItem('note-catcher-'+k);if(old===null)continue;if(localStorage.getItem('spotanote-'+k)===null)localStorage.setItem('spotanote-'+k,old);localStorage.removeItem('note-catcher-'+k)}}catch{}
const pickLang=()=>{const saved=store.get('spotanote-lang');if(LANGS[saved])return saved;const nav=(typeof navigator!=='undefined'&&navigator.languages)||[];for(const l of nav){const code=String(l).slice(0,2).toLowerCase();if(code==='pt')return 'pt-BR';if(code==='iw')return 'he';if(LANGS[code])return code}return 'en'};
let lang=pickLang(),noteSystem=NOTE_SYSTEMS[store.get('spotanote-notes')]?store.get('spotanote-notes'):DEFAULT_NOTES[lang];
function t(key,vars={}){const s=(STRINGS[lang]&&STRINGS[lang][key])??STRINGS.en[key]??key;return s.replace(/\{(\w+)\}/g,(m,k)=>k in vars?vars[k]:m)}
// Octave numbers are written full size after the name (C4, Соль3), as music books and scientific pitch notation do; subscripts were too small to read (Dafa, 11 Nov 2026).
function noteName(p){return NOTE_SYSTEMS[noteSystem].names[p.midi%12]}
function noteWithOctave(p){return noteName(p)+(Math.floor(p.midi/12)-1)}
// Paints every [data-i18n] text and [data-i18n-aria] label; the HTML carries English as its fallback.
function applyI18n(){if(typeof document==='undefined'||!document.documentElement)return;document.documentElement.lang=lang;document.documentElement.dir=RTL.has(lang)?'rtl':'ltr';document.title=t('title');document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)});document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nAria)))}
